import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

const Graph = () => {
    const [data, setData] = useState([]);
    const [timeIndex, setTimeIndex] = useState(0); // Index para las fechas

    // Función para obtener el precio del dólar a pesos mexicanos
    const fetchDollarToMXN = async () => {
        try {
            const response = await axios.get(`https://api.exchangerate-api.com/v4/latest/USD`); // API que proporciona tasas de cambio
            const price = response.data.rates.MXN; // Obtén el tipo de cambio de USD a MXN
            const newDataPoint = { name: `T-${timeIndex}`, price }; // Crea un nuevo punto de datos
            setData((prevData) => [...prevData, newDataPoint]); // Añade el nuevo punto de datos
            setTimeIndex((prevIndex) => prevIndex + 1); // Aumenta el índice del tiempo
        } catch (error) {
            console.error('Error fetching dollar price:', error);
        }
    };

    useEffect(() => {
        fetchDollarToMXN(); // Llama la función al inicio
        const interval = setInterval(fetchDollarToMXN, 10000); // Actualiza cada 10 segundos
        return () => clearInterval(interval); // Limpia el intervalo al desmontar
    }, []);

    return (
        <ResponsiveContainer width="100%" height={200}> {/* Cambié la altura a 200 */}
            <LineChart data={data}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis 
                    tickFormatter={(value) => `$${value.toFixed(2)}`} // Formateo del eje Y
                />
                <Tooltip 
                    formatter={(value) => [`$${value.toFixed(2)}`, 'Precio del Dólar']} 
                />
                <Legend />
                <Line type="monotone" dataKey="price" stroke="#8884d8" />
            </LineChart>
        </ResponsiveContainer>
    );
};

export default Graph;
